CREATE TYPE public.app_role AS ENUM ('learner_tamil','learner_english','coordinator','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', country text NOT NULL DEFAULT 'UK' CHECK (country IN ('UK','Sri Lanka')), timezone text NOT NULL DEFAULT 'Europe/London', age_group text NOT NULL DEFAULT '18+' CHECK (age_group IN ('under 13','13–17','18+')), school text NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}', native_language text NOT NULL DEFAULT 'English', learning_language text NOT NULL DEFAULT 'Tamil', coordinator_id uuid REFERENCES public.profiles(id), onboarded boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (coordinator_id=auth.uid() AND public.has_role(auth.uid(),'coordinator')));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.charity_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, coordinator_id uuid NOT NULL REFERENCES public.profiles(id), charity_name text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.charity_invites TO authenticated; GRANT ALL ON public.charity_invites TO service_role;
ALTER TABLE public.charity_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invites_read ON public.charity_invites FOR SELECT TO authenticated USING ((coordinator_id=auth.uid() AND public.has_role(auth.uid(),'coordinator')) OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_paalam_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
CREATE TRIGGER paalam_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_paalam_profile();
CREATE FUNCTION public.save_paalam_profile(p_display_name text,p_country text,p_timezone text,p_age_group text,p_school text,p_interests text[],p_native_language text,p_learning_language text,p_invite_code text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); existing_role public.app_role; linked uuid; BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to save your profile'; END IF;
IF length(trim(p_display_name))<2 OR length(p_display_name)>80 THEN RAISE EXCEPTION 'Display name must be 2–80 characters'; END IF;
IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_timezone) THEN RAISE EXCEPTION 'Choose a valid IANA timezone'; END IF;
IF p_country NOT IN ('UK','Sri Lanka') OR p_age_group NOT IN ('under 13','13–17','18+') OR p_learning_language NOT IN ('Tamil','English') OR p_native_language NOT IN ('Tamil','English','Other') THEN RAISE EXCEPTION 'Invalid profile choices'; END IF;
IF (p_learning_language='Tamil' AND p_country<>'UK') OR (p_learning_language='English' AND p_country<>'Sri Lanka') THEN RAISE EXCEPTION 'Learning language must match your country'; END IF;
IF length(p_school)>160 OR cardinality(p_interests)>8 OR EXISTS(SELECT 1 FROM unnest(p_interests) i WHERE length(i)>40) THEN RAISE EXCEPTION 'Profile details are too long'; END IF;
SELECT role INTO existing_role FROM public.user_roles WHERE user_id=uid;
SELECT coordinator_id INTO linked FROM public.profiles WHERE id=uid;
IF trim(p_invite_code)<>'' THEN
IF p_country<>'Sri Lanka' THEN RAISE EXCEPTION 'Charity invites are for Sri Lankan students'; END IF;
SELECT i.coordinator_id INTO linked FROM public.charity_invites i WHERE i.code=upper(trim(p_invite_code)) AND i.active AND i.expires_at>now() AND public.has_role(i.coordinator_id,'coordinator');
IF linked IS NULL THEN RAISE EXCEPTION 'That invite code is invalid or expired'; END IF;
END IF;
INSERT INTO public.profiles(id,display_name,country,timezone,age_group,school,interests,native_language,learning_language,coordinator_id,onboarded) VALUES(uid,trim(p_display_name),p_country,p_timezone,p_age_group,trim(p_school),p_interests,p_native_language,p_learning_language,linked,true) ON CONFLICT(id) DO UPDATE SET display_name=EXCLUDED.display_name,country=EXCLUDED.country,timezone=EXCLUDED.timezone,age_group=EXCLUDED.age_group,school=EXCLUDED.school,interests=EXCLUDED.interests,native_language=EXCLUDED.native_language,learning_language=EXCLUDED.learning_language,coordinator_id=EXCLUDED.coordinator_id,onboarded=true;
IF existing_role IS NULL OR existing_role IN ('learner_tamil','learner_english') THEN INSERT INTO public.user_roles(user_id,role) VALUES(uid,CASE WHEN p_learning_language='Tamil' THEN 'learner_tamil'::public.app_role ELSE 'learner_english'::public.app_role END) ON CONFLICT(user_id) DO UPDATE SET role=EXCLUDED.role; END IF;
END $$;
REVOKE ALL ON FUNCTION public.save_paalam_profile(text,text,text,text,text,text[],text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_paalam_profile(text,text,text,text,text,text[],text,text,text) TO authenticated;
CREATE FUNCTION public.create_charity_invite(p_charity_name text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code_value text; BEGIN IF NOT public.has_role(auth.uid(),'coordinator') THEN RAISE EXCEPTION 'Coordinator access required'; END IF; IF length(trim(p_charity_name))<2 OR length(p_charity_name)>120 THEN RAISE EXCEPTION 'Enter a charity name'; END IF; code_value:=upper(replace(gen_random_uuid()::text,'-','')); INSERT INTO public.charity_invites(code,coordinator_id,charity_name) VALUES(code_value,auth.uid(),trim(p_charity_name)); RETURN code_value; END $$;
REVOKE ALL ON FUNCTION public.create_charity_invite(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_charity_invite(text) TO authenticated;
CREATE FUNCTION public.set_paalam_staff_role(p_user_id uuid,p_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF p_user_id=auth.uid() THEN RAISE EXCEPTION 'You cannot change your own role'; END IF; IF p_role NOT IN ('coordinator','admin') THEN RAISE EXCEPTION 'Choose a staff role'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(p_user_id,p_role) ON CONFLICT(user_id) DO UPDATE SET role=EXCLUDED.role; END $$;
REVOKE ALL ON FUNCTION public.set_paalam_staff_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_paalam_staff_role(uuid,public.app_role) TO authenticated;
CREATE INDEX profiles_coordinator_idx ON public.profiles(coordinator_id);